return [{
  json: {
    tenantId: $env.MS_TENANT_ID,
    clientId: $env.MS_CLIENT_ID,
    baselineDays: 30,
    anomalyThreshold: 2 // Z-score threshold
  }
}];

// Calculate baseline statistics per user
const baselineData = $input.item(2).json.baselineSignIns?.value || [];
const userBaselines = {};

// Group by user
for (const signIn of baselineData) {
  const user = signIn.userPrincipalName;
  if (!userBaselines[user]) {
    userBaselines[user] = {
      signInCounts: [],
      ips: new Set(),
      locations: new Set(),
      hours: []
    };
  }

  // Track IPs and locations
  if (signIn.ipAddress) userBaselines[user].ips.add(signIn.ipAddress);
  if (signIn.location?.city) userBaselines[user].locations.add(signIn.location.city);

  // Track sign-in hours
  const hour = new Date(signIn.createdDateTime).getHours();
  userBaselines[user].hours.push(hour);
}

// Calculate statistics
for (const user in userBaselines) {
  const data = userBaselines[user];

  // Daily average sign-ins
  const avgSignInsPerDay = data.hours.length / 30;

  // Standard deviation
  const mean = avgSignInsPerDay;
  const variance = data.hours.map(h => Math.pow(h - mean, 2)).reduce((a, b) => a + b, 0) / data.hours.length;
  const stdDev = Math.sqrt(variance);

  userBaselines[user] = {
    avgSignInsPerDay: avgSignInsPerDay,
    stdDev: stdDev || 1, // Avoid division by zero
    commonIPs: Array.from(data.ips),
    commonLocations: Array.from(data.locations),
    totalSignIns: data.hours.length
  };
}

return [{
  json: {
    userBaselines: userBaselines,
    baselineCalculated: true
  }
}];

// Calculate anomaly features and detect anomalies
const recentSignIns = $input.item(0).json.signIns?.value || [];
const fileAccess = $input.item(1).json.fileAccess?.value || [];
const baselines = $node['Calculate Baseline'].json.userBaselines;
const threshold = $node['Set Config'].json.anomalyThreshold;

const anomalies = [];

// Group recent activity by user
const userActivity = {};
for (const signIn of recentSignIns) {
  const user = signIn.userPrincipalName;
  if (!userActivity[user]) {
    userActivity[user] = {
      signInCount: 0,
      uniqueIPs: new Set(),
      uniqueLocations: new Set(),
      hours: []
    };
  }
  userActivity[user].signInCount++;
  if (signIn.ipAddress) userActivity[user].uniqueIPs.add(signIn.ipAddress);
  if (signIn.location?.city) userActivity[user].uniqueLocations.add(signIn.location.city);
  userActivity[user].hours.push(new Date(signIn.createdDateTime).getHours());
}

// File access by user
const fileAccessByUser = {};
for (const access of fileAccess) {
  const user = access.initiatedBy?.user?.userPrincipalName;
  if (user) {
    fileAccessByUser[user] = (fileAccessByUser[user] || 0) + 1;
  }
}

// Detect anomalies
for (const user in userActivity) {
  const activity = userActivity[user];
  const baseline = baselines[user];

  if (!baseline) continue; // No baseline for new users

  // Calculate z-scores
  const signInZScore = Math.abs((activity.signInCount - baseline.avgSignInsPerDay) / baseline.stdDev);
  const newIPCount = Array.from(activity.uniqueIPs).filter(ip => !baseline.commonIPs.includes(ip)).length;
  const newLocationCount = Array.from(activity.uniqueLocations).filter(loc => !baseline.commonLocations.includes(loc)).length;

  // Unusual hours (outside 6 AM - 10 PM)
  const unusualHours = activity.hours.filter(h => h < 6 || h > 22).length;
  const unusualHoursRatio = unusualHours / activity.hours.length;

  // File access deviation
  const fileCount = fileAccessByUser[user] || 0;
  const fileAccessDeviation = fileCount > 50 ? fileCount / 10 : 0; // Simple heuristic

  // Combined anomaly score
  const anomalyScore = Math.max(signInZScore, newIPCount, newLocationCount * 2, unusualHoursRatio * 10, fileAccessDeviation);

  if (anomalyScore > threshold) {
    anomalies.push({
      userPrincipalName: user,
      anomalyScore: Math.round(anomalyScore * 100) / 100,
      signInZScore: Math.round(signInZScore * 100) / 100,
      newIPCount: newIPCount,
      newLocationCount: newLocationCount,
      unusualHoursRatio: Math.round(unusualHoursRatio * 100),
      fileAccessCount: fileCount,
      recentSignIns: activity.signInCount,
      baselineSignIns: Math.round(baseline.avgSignInsPerDay),
      timestamp: new Date().toISOString()
    });
  }
}

return anomalies.map(a => ({json: a}));

// Prepare LLM explanation prompt
const anomaly = $input.first().json;

const prompt = `Analyze this user behavior anomaly and provide threat assessment.

**User Activity Anomaly:**
- User: ${anomaly.userPrincipalName}
- Anomaly Score: ${anomaly.anomalyScore} (threshold: 2.0)
- Sign-In Deviation: ${anomaly.signInZScore}x standard deviation
- New IPs: ${anomaly.newIPCount}
- New Locations: ${anomaly.newLocationCount}
- Unusual Hours: ${anomaly.unusualHoursRatio}%
- File Downloads: ${anomaly.fileAccessCount}
- Recent Sign-Ins: ${anomaly.recentSignIns} (baseline: ${anomaly.baselineSignIns})

**Analysis Required:**
1. Assess likelihood of account compromise
2. Determine threat level
3. Recommend graduated response (MFA, session revoke, account disable)
4. Provide clear explanation for security team

**Required Response Format (JSON only):**
{
  "threatLevel": "low/medium/high/critical",
  "compromiseLikelihood": 0-100,
  "explanation": "clear explanation of anomaly",
  "possibleCauses": ["list of possible explanations"],
  "actions": [
    {"action": "specific action", "urgency": "immediate/high/medium/low"}
  ],
  "requiresMFA": true/false,
  "requiresSessionRevoke": true/false,
  "requiresAccountDisable": true/false
}

Respond with ONLY the JSON object.`;

return [{
  json: {
    prompt: prompt,
    anomalyData: anomaly
  }
}];

// Parse LLM response
const response = $input.first().json;
const anomalyData = $node['Prepare LLM Prompt'].json.anomalyData;

function extractJSON(llmResponse) {
  let text;
  if (llmResponse.choices?.[0]?.message?.content) text = llmResponse.choices[0].message.content;
  else if (llmResponse.content?.[0]?.text) text = llmResponse.content[0].text;
  else if (llmResponse.candidates?.[0]?.content?.parts?.[0]?.text) text = llmResponse.candidates[0].content.parts[0].text;
  else if (llmResponse.response) text = llmResponse.response;
  else text = llmResponse.text || JSON.stringify(llmResponse);

  text = text.replace(/```json\n?|```\n?/g, '').trim();
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  return JSON.parse(jsonMatch ? jsonMatch[0] : text);
}

try {
  const analysis = extractJSON(response);
  return [{
    json: {
      user: anomalyData.userPrincipalName,
      anomaly: anomalyData,
      aiAnalysis: analysis,
      threatLevel: analysis.threatLevel,
      requiresMFA: analysis.requiresMFA,
      requiresSessionRevoke: analysis.requiresSessionRevoke,
      isHighThreat: ['high', 'critical'].includes(analysis.threatLevel),
      timestamp: new Date().toISOString()
    }
  }];
} catch (error) {
  return [{
    json: {
      user: anomalyData.userPrincipalName,
      anomaly: anomalyData,
      aiAnalysis: { error: error.message },
      threatLevel: 'medium',
      requiresMFA: true,
      requiresSessionRevoke: false,
      isHighThreat: false,
      timestamp: new Date().toISOString()
    }
  }];
}

// Format anomaly detection alert
const data = $input.first().json;
const analysis = data.aiAnalysis;
const anomaly = data.anomaly;

let message = `🔍 *Behavioral Anomaly Detected*\n\n`;
message += `*User:* ${data.user}\n`;
message += `*Threat Level:* ${data.threatLevel.toUpperCase()}\n`;
message += `*Anomaly Score:* ${anomaly.anomalyScore}\n`;
message += `*Compromise Likelihood:* ${analysis.compromiseLikelihood || 'N/A'}%\n\n`;

message += `*Anomaly Details:*\n`;
message += `• Sign-In Deviation: ${anomaly.signInZScore}x normal\n`;
message += `• New IPs: ${anomaly.newIPCount}\n`;
message += `• New Locations: ${anomaly.newLocationCount}\n`;
message += `• Unusual Hours: ${anomaly.unusualHoursRatio}%\n`;
message += `• File Downloads: ${anomaly.fileAccessCount}\n\n`;

message += `*AI Analysis:*\n${analysis.explanation}\n\n`;

if (analysis.possibleCauses) {
  message += `*Possible Causes:*\n`;
  analysis.possibleCauses.forEach(cause => {
    message += `• ${cause}\n`;
  });
  message += `\n`;
}

if (data.isHighThreat) {
  message += `⚠️ *Automated Response:*\n`;
  if (data.requiresMFA) message += `• ✅ MFA challenge required\n`;
  if (data.requiresSessionRevoke) message += `• ✅ Sessions revoked\n`;
}

message += `\nTimestamp: ${data.timestamp}`;

return [{
  json: {
    channel: '#security-alerts',
    text: message,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: '🔍 Anomaly Detected',
          emoji: true
        }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: message
        }
      }
    ]
  }
}];
